var ORBIT='<svg class="orbit" viewBox="0 0 260 260" aria-hidden="true"><g fill="none" stroke="#fff" stroke-opacity=".35" stroke-width="1.4"><ellipse cx="130" cy="130" rx="110" ry="40"/><ellipse cx="130" cy="130" rx="110" ry="40" transform="rotate(60 130 130)"/><ellipse cx="130" cy="130" rx="110" ry="40" transform="rotate(120 130 130)"/></g><circle cx="130" cy="130" r="10" fill="#fff" fill-opacity=".5"/><circle cx="240" cy="130" r="5" fill="#d7ff4a"/><circle cx="75" cy="35" r="4" fill="#fff" fill-opacity=".8"/></svg>';
