var SPROUT='<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 21v-9" stroke="#16a34a" stroke-width="2.2" stroke-linecap="round" fill="none"/><path d="M12 13C7 13 4 9 5 5c5 0 8 4 7 8z" fill="#22c55e"/><path d="M12 11c4 0 7-3 7-7-4 0-7 3-7 7z" fill="#34d399"/></svg>';
function shuffle(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a}
