/* ---- PDF download ---- */
var dlP=(window.claude&&window.claude.use)?window.claude.use('downloads').catch(function(){return null}):Promise.resolve(null);
function downloadPdf(n,btn,hint){
  var url=PDF+'ch-'+pad(n)+'.pdf',fn='ArifsLoop-Class-'+(cur.cls==9?'9-10':cur.cls)+'-Science-Chapter-'+pad(n)+'.pdf';
  function direct(){var l=document.createElement('a');l.href=url;l.download=fn;l.target='_blank';l.rel='noopener';document.body.appendChild(l);l.click();l.remove();hint.className='hint';hint.textContent='PDF খোলা হচ্ছে… না খুললে pdf ফোল্ডারটি index.html-এর পাশে আছে কিনা দেখো।'}
  hint.className='hint';btn.disabled=true;hint.textContent='PDF তৈরি হচ্ছে…';
  dlP.then(function(api){
    if(!api&&location.protocol==='file:'){direct();return}
    return fetch(url).then(function(r){if(!r.ok)throw new Error('fetch');return r.blob()}).then(function(blob){
      if(!api){var u=URL.createObjectURL(blob),l=document.createElement('a');l.href=u;l.download=fn;document.body.appendChild(l);l.click();l.remove();setTimeout(function(){URL.revokeObjectURL(u)},4000);hint.textContent='PDF সেভ হয়েছে।';return}
      return api.save({filename:fn,data:blob}).then(function(){hint.textContent='PDF সেভ হয়েছে।'})
    },function(e){if(!api){direct();return}throw e})
  })
  .catch(function(e){var c=e&&e.code;hint.className='hint'+(c==='declined'?'':' err');
    hint.textContent=c==='declined'?'ডাউনলোড বাতিল করা হয়েছে।':c==='rate_limited'?'একটু পরে আবার চেষ্টা করো।':'PDF নামানো যায়নি। আবার চেষ্টা করো।'})
  .then(function(){btn.disabled=false});
}

